```js
import { defineConfig } from 'rolldown';

export default defineConfig({
  output: {
    codeSplitting: {
      groups: [
        {
          name: 'react',
          test: /node_modules[\\/]react/,
          priority: 2,
        },
        {
          name: 'other-libs',
          test: /node_modules/,
          priority: 1,
        },
      ],
    },
  },
});
```

